CREATE TABLE IF NOT EXISTS notifications (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NULL,type VARCHAR(64) NOT NULL,title VARCHAR(220) NOT NULL,message VARCHAR(1000) NOT NULL,deep_link VARCHAR(512) NULL,payload JSON NULL,read_at DATETIME(6) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_notification_user(user_id,read_at,created_at));
CREATE TABLE IF NOT EXISTS device_tokens (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,platform VARCHAR(16) NOT NULL,token VARCHAR(512) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),INDEX idx_device_user(user_id,active));
CREATE TABLE IF NOT EXISTS notification_preferences (user_id CHAR(36) NOT NULL,type VARCHAR(64) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(user_id,type));
